import{_ as c,r as n,o as r,c as l,e as t,a,d as e,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"设置计划任务 - October CMS - 3.x","titleTemplate":false,"description":"了解如何运行计划任务和队列。","frontmatter":{"subtitle":"了解如何运行计划任务和队列。"},"headers":[{"level":2,"title":"设置队列工作进程","slug":"设置队列工作进程","link":"#设置队列工作进程","children":[]},{"level":2,"title":"无命令行环境下的 Cron","slug":"无命令行环境下的-cron","link":"#无命令行环境下的-cron","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/setup/scheduler.md","filePath":"3.x/zh-cn/setup/scheduler.md"}'),d={name:"3.x/zh-cn/setup/scheduler.md"};function u(h,s,g,k,m,v){const o=n("pre-heading"),p=n("post-heading");return r(),l("div",null,[t(o),s[0]||(s[0]=a("h1",null,"设置计划任务",-1)),t(p),s[1]||(s[1]=a("p",null,[e("为了使计划任务正常运行，请将以下 "),a("a",{href:"https://www.cyberciti.biz/faq/how-do-i-add-jobs-to-cron-under-linux-or-unix-oses/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("Cron job"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),a("span",{class:"sr-only"},"(opens new window)")])]),e(" 添加到服务器：")],-1)),s[2]||(s[2]=i(`<div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * php /october/artisan schedule:run <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div><p>请确保将 <code>/october/artisan</code> 替换为 October CMS 安装目录中 artisan 文件的绝对路径。此 Cron job 将每分钟调用一次命令调度器。然后 October CMS 会评估所有计划任务并运行到期的任务。</p><div class="custom-block tip"><p>当将 crontab 文件添加到 /etc/cron.d 时，需要在 <code>* * * * *</code> 之后指定用户名：</p><div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * alice php /october/artisan schedule:run <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div></div><h2 id="设置队列工作进程"><a href="#设置队列工作进程" class="header-anchor">#</a> 设置队列工作进程</h2><p>您可以选择设置队列驱动来处理<a href="./../extend/services/queue.html">队列任务</a>。队列驱动可以在 <code>config/queue.php</code> 文件中进行配置。</p><p>对于数据库队列驱动，您可以设置一个 Cron job 来运行调用队列中第一个可用任务的命令：<code>php artisan queue:work --once</code>。</p><div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * php /october/artisan queue:work <span class="token parameter variable">--once</span> <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div><p>或者，也可以将队列作为守护进程运行</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan queue:work
</code></pre></div><h2 id="无命令行环境下的-cron"><a href="#无命令行环境下的-cron" class="header-anchor">#</a> 无命令行环境下的 Cron</h2><p>如果您的主机提供商未提供 Cron 表，您可以改为每隔 X 分钟调用一个公共 URL。例如，如果某个插件要求您每 15 分钟运行以下命令。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan campaign:run
</code></pre></div><p>这需要一些 PHP 编码作为解决方案，使用 <code>Artisan</code> facade 配合<a href="./../extend/system/routing.html">路由文件</a>来构建一个调用此命令的端点。例如，一个 <strong>routes.php</strong> 文件可能包含以下内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/campaign-run&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;campaign:run&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当打开 URL <code>/campaign-run</code> 时，artisan 命令将被调用。</p><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../extend/system/scheduling.html">任务调度</a></li><li><a href="./../extend/services/queue.html">队列</a></li></ul></div>`,17))])}const x=c(d,[["render",u]]);export{b as __pageData,x as default};
